def set_meta(text: str, page: dict) -> str:
    url = f"{BASE}/{page['slug']}/"
    text = re.sub(r'<title>.*?</title>', f"<title>{html.escape(page['title'])}</title>", text, count=1, flags=re.S|re.I)
    for name, value in [('description',page['desc']),('og:title',page['title']),('og:description',page['desc']),('twitter:title',page['title']),('twitter:description',page['desc'])]:
        if name.startswith('og:'):
            pat = rf'<meta[^>]+property=["\']{re.escape(name)}["\'][^>]*>'
            repl = f'<meta property="{name}" content="{html.escape(value, quote=True)}"/>'
        else:
            pat = rf'<meta[^>]+name=["\']{re.escape(name)}["\'][^>]*>'
            repl = f'<meta name="{name}" content="{html.escape(value, quote=True)}"/>'
        if re.search(pat,text,re.I): text = re.sub(pat,repl,text,count=1,flags=re.I)
        else: text = text.replace('</head>', repl+'</head>',1)
    text = re.sub(r'<link[^>]+rel=["\']canonical["\'][^>]*>', f'<link rel="canonical" href="{url}"/>', text, count=1, flags=re.I)
    text = re.sub(r'<meta[^>]+property=["\']og:url["\'][^>]*>', f'<meta property="og:url" content="{url}"/>', text, count=1, flags=re.I)
    text = re.sub(r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>.*?</script>', '', text, flags=re.I|re.S)
    faq = [{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in page['faqs']]
    schemas = [
      {'@context':'https://schema.org','@type':'WebPage','name':page['title'].split('|')[0].strip(),'url':url,'description':page['desc'],'inLanguage':'ru-RU'},
      {'@context':'https://schema.org','@type':'Service','@id':url+'#service','name':page['title'].split('|')[0].strip(),'url':url,'description':page['desc'],'provider':{'@id':BASE+'/#person'},'areaServed':'Worldwide'},
      {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Главная','item':BASE+'/'},{'@type':'ListItem','position':2,'name':'Услуги','item':BASE+'/services/'},{'@type':'ListItem','position':3,'name':page['title'].split('|')[0].strip(),'item':url}]},
      {'@context':'https://schema.org','@type':'FAQPage','mainEntity':faq},
    ]
    blob = ''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False,separators=(',',':'))+'</script>' for s in schemas)
    text = text.replace('</head>', blob+'</head>',1)
    text = re.sub(r'(<body\b[^>]*\bdata-page=["\'])[^"\']*(["\'])', lambda m: m.group(1)+page['slug']+m.group(2), text, count=1, flags=re.I)
    return text


def main_html(p: dict) -> str:
    proute,pname,pimg,pw,ph,pdesc=p['proof']
    outcomes=''.join(f'<article class="p129-outcome"><span>0{i}</span><h3>{html.escape(h)}</h3><p>{html.escape(c)}</p></article>' for i,(h,c) in enumerate(p['outcomes'],1))
    tasks=''.join(f'<article class="secondary-demand__card"><h3>{html.escape(h)}</h3><p>{html.escape(c)}</p></article>' for h,c in p['tasks'])
    rel=''.join(f'<a href="{u}"><span>Следующий шаг</span><strong>{html.escape(t)}</strong><b>↗</b></a>' for u,t in p['related'])
    faq=''.join(f'<article class="secondary-demand__card"><h3>{html.escape(q)}</h3><p>{html.escape(a)}</p></article>' for q,a in p['faqs'])
    return f'''<main id="main-content" class="p129-service" data-stage129-service="true" data-stage172="{p['slug']}">
<section class="p129-svc-hero p155-service-hero" data-stage155-service-scene="true"><div class="p155-service-band"><div class="p129-svc-copy"><p class="p129-kicker"><i></i>{html.escape(p['kicker'])}</p><h1>{p['h1']}</h1><p class="p129-lead">{html.escape(p['lead'])}</p><div class="p129-svc-actions"><a class="p129-btn" href="https://t.me/Alexuys" target="_blank" rel="noopener noreferrer">Обсудить задачу ↗</a><a class="p129-textlink" href="#result">Что получится ↓</a></div></div></div><div class="p155-service-preview"><aside class="p129-svc-board"><span class="p129-svc-no">{p['no']}</span><h2>Фокус на результате.</h2><ul>{''.join('<li>'+html.escape(x[0])+'</li>' for x in p['outcomes'])}</ul></aside></div></section>
<section class="p129-outcomes wow-reveal" id="result"><div class="p129-shell"><div class="p129-section-head"><p class="p129-kicker">RESULT / {p['no']}</p><h2>Не просто функция. <span>Рабочий пользовательский сценарий.</span></h2></div><div class="p129-outcome-list">{outcomes}</div></div></section>
<section class="p129-case wow-reveal"><div class="p129-shell"><a class="p129-case-card wow-reveal" href="{proute}"><div class="p129-case-media wow-reveal"><img width="{pw}" height="{ph}" src="{pimg}" alt="{html.escape(pname)}" loading="lazy" decoding="async"></div><div class="p129-case-copy wow-reveal"><span class="p129-kicker"><i></i>REAL WORK</span><h2>{html.escape(pname)}</h2><p>{html.escape(pdesc)}</p><span class="p129-textlink">Открыть кейс ↗</span></div></a></div></section>
<section class="secondary-demand" data-stage172-tasks="true"><div class="secondary-demand__shell"><div class="secondary-demand__head"><p class="secondary-demand__eyebrow">TASKS</p><div><h2>С какими задачами сюда приходят.</h2><p class="secondary-demand__intro">Страница заточена под конкретный поисковый запрос, но услуга не собирается из шаблона: сначала фиксируется нужный результат, существующая система и ограничения.</p></div></div><div class="secondary-demand__grid">{tasks}</div></div></section>
<section class="p129-related wow-reveal"><div class="p129-shell"><div class="p129-section-head"><p class="p129-kicker">EXPLORE</p><h2>Связанные направления. <span>Без дублирования одной услуги разными словами.</span></h2></div><div class="p129-related-grid wow-reveal">{rel}</div></div></section>
<section class="secondary-demand" data-stage172-faq="true"><div class="secondary-demand__shell"><div class="secondary-demand__head"><p class="secondary-demand__eyebrow">FAQ</p><div><h2>Перед стартом.</h2><p class="secondary-demand__intro">Короткие ответы на вопросы, которые обычно появляются до оценки задачи.</p></div></div><div class="secondary-demand__grid">{faq}</div></div></section>
<section class="p129-contact wow-reveal"><div class="p129-shell"><div class="p129-contact-card wow-reveal"><div><p class="p129-kicker">START</p><h2>Покажите, что должно заработать.</h2><p>Для первого сообщения достаточно ссылки, текущего состояния и желаемого результата. Если проекта ещё нет — опишите основной пользовательский сценарий.</p></div><a class="p129-btn" href="https://t.me/Alexuys" target="_blank" rel="noopener noreferrer">Написать в Telegram ↗</a></div></div></section>
</main>'''

for p in PAGES:
    text = set_meta(TEMPLATE_HTML, p)
    text = re.sub(r'<main\b.*?</main>', main_html(p), text, count=1, flags=re.I|re.S)
    dest = ROOT / p['slug'] / 'index.html'
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(text, encoding='utf-8')

# Broaden the two top-level search entry points without turning the home page into a keyword list.
home = ROOT/'index.html'
ht = home.read_text(encoding='utf-8')
ht = re.sub(r'<title>.*?</title>', '<title>Разработчик на заказ - сайты, боты и автоматизация | Alexuys</title>', ht, count=1, flags=re.S|re.I)
ht = re.sub(r'<meta[^>]+name=["\']description["\'][^>]*>', '<meta name="description" content="Разработчик на заказ: сайты и веб-сервисы, Telegram-боты, CRM, backend, API, автоматизация, Python и доработка существующих проектов."/>', ht, count=1, flags=re.I)
home.write_text(ht,encoding='utf-8')

dev = ROOT/'development'/'index.html'
dt = dev.read_text(encoding='utf-8')
dt = re.sub(r'<title>.*?</title>', '<title>Программист на заказ - сайты, приложения и автоматизация | Alexuys</title>', dt, count=1, flags=re.S|re.I)
dt = re.sub(r'<meta[^>]+name=["\']description["\'][^>]*>', '<meta name="description" content="Программист на заказ для веб-сервисов, сайтов, Telegram-ботов, CRM, backend, API, Python, автоматизации и доработки существующих проектов."/>', dt, count=1, flags=re.I)
dt = dt.replace('Разработка под задачу. <em>Формат выберем после разбора.</em>', 'Программист под задачу. <em>От небольшого скрипта до веб-сервиса.</em>', 1)
dev.write_text(dt,encoding='utf-8')

# Add a discoverable commercial index to the services hub.
svc = ROOT/'services'/'index.html'
st = svc.read_text(encoding='utf-8')
links = ''.join(f'<a href="/{p["slug"]}/"><strong>{html.escape(p["title"].split("|")[0].strip())}</strong><span>{html.escape(p["desc"].split(":",1)[-1].strip()[:105])}</span></a>' for p in PAGES)
block = f'''<section class="p130-list-section stage172-service-expansion" data-stage172-hub="true"><div class="p130-shell"><div class="p129-section-head"><p class="p130-kicker">MORE TASKS</p><h2>Отдельные входы под конкретную задачу.</h2></div><div class="p130-list">{links}</div></div></section>'''
st, n = re.subn(r'<section class="([^"]*\bp130-footer-cta\b[^"]*)"', lambda m: block+'<section class="'+m.group(1)+'"', st, count=1)
if n != 1: raise SystemExit('stage172: services hub insertion failed')
svc.write_text(st,encoding='utf-8')

# Build a real internal-link graph from existing authority pages into the new intent pages.
SOURCE_LINKS = {
 '/development/': [p['slug'] for p in PAGES],
 '/web-development/': ['personal-cabinet-development','admin-panel-development','saas-development','ecommerce-development','site-repair','tilda-development'],
 '/api-integrations/': ['1c-integration','payment-integration','personal-cabinet-development','admin-panel-development'],
 '/python-development/': ['python-scripts','web-scraping-parsers','excel-google-sheets-automation','ai-chatbot-development'],
 '/ai-automation/': ['ai-chatbot-development','excel-google-sheets-automation','python-scripts'],
 '/project-repair/': ['site-repair','tilda-development','bitrix-development'],
 '/crm-development/': ['crm-integration','admin-panel-development','personal-cabinet-development','1c-integration'],
 '/n8n-automation/': ['excel-google-sheets-automation','ai-chatbot-development','payment-integration','1c-integration'],
 '/wordpress-development/': ['site-repair','ecommerce-development','payment-integration'],
 '/backend-development/': ['api-development','saas-development','admin-panel-development','payment-integration','web-scraping-parsers'],
}
by_slug={p['slug']:p for p in PAGES}
for route, slugs in SOURCE_LINKS.items():
    fp=ROOT/route.strip('/')/'index.html'
    if not fp.is_file(): continue
    x=fp.read_text(encoding='utf-8')
    if 'data-stage172-crosslinks="true"' in x: continue
    SHORT_LABELS = {
      'personal-cabinet-development':'Личный кабинет','admin-panel-development':'Админ-панель','saas-development':'SaaS-сервис','ecommerce-development':'Интернет-магазин',
      'excel-google-sheets-automation':'Excel / Google Sheets','python-scripts':'Python-скрипты','web-scraping-parsers':'Парсеры данных','automation-services':'Автоматизация процессов',
      '1c-integration':'Интеграция 1С','payment-integration':'Онлайн-оплата','crm-integration':'CRM-интеграции','api-development':'Разработка API',
      'site-repair':'Доработка сайта','ai-chatbot-development':'AI-ассистенты','tilda-development':'Tilda','bitrix-development':'1С-Битрикс',
    }
    GROUPS = [
      ('01 / PRODUCTS','Продукты и кабинеты',['personal-cabinet-development','admin-panel-development','saas-development','ecommerce-development']),
      ('02 / AUTOMATION','Автоматизация и данные',['excel-google-sheets-automation','python-scripts','web-scraping-parsers','automation-services']),
      ('03 / INTEGRATIONS','Интеграции',['1c-integration','payment-integration','crm-integration','api-development']),
      ('04 / SUPPORT + AI','Доработка и AI',['site-repair','ai-chatbot-development','tilda-development','bitrix-development']),
    ]
    cards=[]
    selected=set(slugs)
    for eyebrow, title, members in GROUPS:
        members=[m for m in members if m in selected]
        if not members: continue
        rows=''.join(
          f'<a href="/{m}/"><strong>{html.escape(SHORT_LABELS.get(m,m))}</strong><span>Открыть направление</span><b>↗</b></a>'
          for m in members
        )
        cards.append(f'<article class="stage172-task-map__group"><p>{eyebrow}</p><h3>{html.escape(title)}</h3><nav aria-label="{html.escape(title)}">{rows}</nav></article>')
    cross=f'<section class="stage172-task-map" data-stage172-crosslinks="true"><div class="stage172-task-map__shell"><div class="stage172-task-map__head"><p class="stage172-task-map__eyebrow">RELATED TASKS</p><div><h2>Следующий шаг - по типу задачи.</h2><p>Не список технологий, а понятные направления: продукт, автоматизация, интеграция или доработка.</p></div></div><div class="stage172-task-map__grid">{''.join(cards)}</div></div></section>'
    markers=[r'<section class="p129-contact', r'<section class="s165-bridge', r'</main>']
    done=False
    for marker in markers:
        m=re.search(marker,x,re.I)
        if m:
            x=x[:m.start()]+cross+x[m.start():]
            done=True; break
    if not done: raise SystemExit(f'stage172 crosslink insertion failed {route}')
    fp.write_text(x,encoding='utf-8')

# Sitemap and text discovery files.
urls=[f'{BASE}/{p["slug"]}/' for p in PAGES]
for fname in ('sitemap.xml','sitemap-google.xml'):
    fp=ROOT/fname
    if not fp.exists(): continue
    x=fp.read_text(encoding='utf-8')
    add=''.join(f'<url><loc>{u}</loc><lastmod>{TODAY}</lastmod><changefreq>weekly</changefreq><priority>0.8</priority></url>' for u in urls if u not in x)
    if add:
        x=x.replace('</urlset>',add+'</urlset>',1)
        fp.write_text(x,encoding='utf-8')
for fname in ('sitemap.txt',):
    fp=ROOT/fname
    if fp.exists():
        existing=fp.read_text(encoding='utf-8').splitlines()
        merged=existing+[u for u in urls if u not in existing]
        fp.write_text('\n'.join(merged)+'\n',encoding='utf-8')
llms=ROOT/'llms.txt'
if llms.exists():
    x=llms.read_text(encoding='utf-8')
    section='\n## Дополнительные услуги\n'+'\n'.join(f'- {p["title"].split("|")[0].strip()}: {BASE}/{p["slug"]}/' for p in PAGES)+'\n'
    if '## Дополнительные услуги' not in x:
        llms.write_text(x.rstrip()+section,encoding='utf-8')

# Guardrails: every page exists, canonical is unique, and all routes are in sitemap.
smap=(ROOT/'sitemap.xml').read_text(encoding='utf-8')
for p in PAGES:
    path=ROOT/p['slug']/'index.html'; text=path.read_text(encoding='utf-8'); url=f'{BASE}/{p["slug"]}/'
    if text.count(f'<link rel="canonical" href="{url}"/>') != 1: raise SystemExit(f'stage172 canonical failed {p["slug"]}')
    if '<h1>' not in text or 'data-stage172=' not in text: raise SystemExit(f'stage172 content failed {p["slug"]}')
    if smap.count(f'<loc>{url}</loc>') != 1: raise SystemExit(f'stage172 sitemap failed {p["slug"]}')
print(f'stage172 search expansion: created={len(PAGES)}; broad home/development entrypoints updated; services hub expanded')
